<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>MedBook — Find and Book Top Doctors Instantly</title>
  <script src="https://cdn.tailwindcss.com"></script>
  <script src="https://unpkg.com/lucide@latest/dist/umd/lucide.min.js"></script>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet">
  <script>
    tailwind.config = {
      theme: {
        extend: {
          colors: {
            navy: { 50: '#EDEBF7', 100: '#D5D0ED', 200: '#A99EDC', 300: '#7D6CCB', 400: '#513ABA', 500: '#2D2A8C', 600: '#1B1464', 700: '#15104F', 800: '#0F0C3A', 900: '#090725' },
            accent: { 50: '#FFFBE6', 100: '#FFF5B8', 200: '#FFED80', 300: '#FFE548', 400: '#FFD930', 500: '#FFC800', 600: '#E6B400', 700: '#B38D00', 800: '#806600', 900: '#4D3F00' },
            mint: { 50: '#ECFDF5', 100: '#D1FAE5', 400: '#34D399', 500: '#10B981', 600: '#059669' }
          },
          fontFamily: { sans: ['Inter', 'system-ui', 'sans-serif'] }
        }
      }
    }
  </script>
  <style>
    * { font-family: 'Inter', system-ui, sans-serif; }

    /* Smooth scrolling */
    html { scroll-behavior: smooth; }

    /* Search autocomplete dropdown */
    .autocomplete-dropdown {
      position: absolute;
      top: 100%;
      left: 0;
      right: 0;
      background: white;
      border: 1px solid #E5E7EB;
      border-top: none;
      border-radius: 0 0 0.75rem 0.75rem;
      box-shadow: 0 10px 25px -5px rgba(27,20,100,0.12);
      z-index: 50;
      max-height: 260px;
      overflow-y: auto;
      display: none;
    }
    .autocomplete-dropdown.active { display: block; }
    .autocomplete-item {
      padding: 0.65rem 1rem;
      cursor: pointer;
      transition: background 120ms ease;
      display: flex;
      align-items: center;
      gap: 0.6rem;
      font-size: 0.9rem;
      color: #374151;
    }
    .autocomplete-item:hover, .autocomplete-item.highlighted {
      background: #F3F0FF;
      color: #1B1464;
    }
    .autocomplete-item:first-child { padding-top: 0.75rem; }
    .autocomplete-item:last-child { padding-bottom: 0.75rem; border-radius: 0 0 0.75rem 0.75rem; }

    /* Mobile menu slide-out */
    .mobile-menu-overlay {
      position: fixed; inset: 0;
      background: rgba(27,20,100,0.3);
      backdrop-filter: blur(4px);
      z-index: 90;
      opacity: 0;
      pointer-events: none;
      transition: opacity 250ms ease;
    }
    .mobile-menu-overlay.active { opacity: 1; pointer-events: auto; }

    .mobile-menu-drawer {
      position: fixed; top: 0; right: 0; bottom: 0;
      width: 280px; max-width: 85vw;
      background: white;
      z-index: 100;
      transform: translateX(100%);
      transition: transform 300ms ease-out;
      box-shadow: -8px 0 30px rgba(27,20,100,0.15);
    }
    .mobile-menu-drawer.active { transform: translateX(0); }

    /* Fade-in animation */
    .fade-in-up {
      opacity: 0;
      transform: translateY(24px);
      transition: opacity 500ms ease-out, transform 500ms ease-out;
    }
    .fade-in-up.visible {
      opacity: 1;
      transform: translateY(0);
    }

    /* Staggered children */
    .stagger-children .fade-in-up:nth-child(1) { transition-delay: 0ms; }
    .stagger-children .fade-in-up:nth-child(2) { transition-delay: 80ms; }
    .stagger-children .fade-in-up:nth-child(3) { transition-delay: 160ms; }
    .stagger-children .fade-in-up:nth-child(4) { transition-delay: 240ms; }
    .stagger-children .fade-in-up:nth-child(5) { transition-delay: 320ms; }
    .stagger-children .fade-in-up:nth-child(6) { transition-delay: 400ms; }

    /* Card hover lift */
    .card-lift {
      transition: transform 200ms ease, box-shadow 200ms ease;
    }
    .card-lift:hover {
      transform: translateY(-4px);
      box-shadow: 0 12px 32px -8px rgba(27,20,100,0.16);
    }

    /* Button press */
    .btn-press { transition: transform 100ms ease, box-shadow 150ms ease; }
    .btn-press:active { transform: scale(0.97); }

    /* Specialty card icon pulse on hover */
    .specialty-icon { transition: transform 200ms ease, background 200ms ease; }
    .specialty-card:hover .specialty-icon {
      transform: scale(1.1);
      background: #1B1464;
      color: #FFD930;
    }
    .specialty-card:hover .specialty-icon svg { stroke: #FFD930; }

    /* Step connector line */
    .step-connector {
      position: absolute;
      top: 2rem;
      left: calc(50% + 2rem);
      width: calc(100% - 4rem);
      height: 2px;
      background: repeating-linear-gradient(90deg, #D5D0ED 0, #D5D0ED 8px, transparent 8px, transparent 16px);
    }

    /* Stats counter animation */
    @keyframes countUp {
      from { opacity: 0; transform: translateY(12px); }
      to { opacity: 1; transform: translateY(0); }
    }
    .stat-item { animation: countUp 600ms ease-out both; }
    .stat-item:nth-child(1) { animation-delay: 0ms; }
    .stat-item:nth-child(2) { animation-delay: 120ms; }
    .stat-item:nth-child(3) { animation-delay: 240ms; }
    .stat-item:nth-child(4) { animation-delay: 360ms; }

    /* Search field focus ring */
    .search-field:focus-within {
      border-color: #FFD930;
      box-shadow: 0 0 0 3px rgba(255,217,48,0.25);
    }

    /* Testimonial quote mark */
    .quote-mark {
      font-size: 4rem;
      line-height: 1;
      color: #FFD930;
      font-family: Georgia, serif;
      position: absolute;
      top: -0.25rem;
      left: 0.5rem;
      opacity: 0.6;
    }

    /* Custom scrollbar for autocomplete */
    .autocomplete-dropdown::-webkit-scrollbar { width: 6px; }
    .autocomplete-dropdown::-webkit-scrollbar-track { background: transparent; }
    .autocomplete-dropdown::-webkit-scrollbar-thumb { background: #D5D0ED; border-radius: 3px; }
  </style>
</head>
<body class="bg-white text-gray-800 antialiased">

  <!-- ============ HEADER ============ -->
  <header id="header" class="sticky top-0 z-50 bg-white/95 backdrop-blur-md border-b border-gray-100 transition-shadow duration-300">
    <div class="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
      <div class="flex items-center justify-between h-16">
        <!-- Logo -->
        <a href="#" class="flex items-center gap-2 group">
          <div class="w-9 h-9 bg-navy-600 rounded-lg flex items-center justify-center group-hover:bg-navy-500 transition-colors">
            <i data-lucide="heart-pulse" class="w-5 h-5 text-accent-400"></i>
          </div>
          <span class="text-xl font-bold text-navy-600">Med<span class="text-accent-400">Book</span></span>
        </a>

        <!-- Desktop nav -->
        <nav class="hidden md:flex items-center gap-1">
          <a href="#specialties" class="px-4 py-2 text-sm font-medium text-gray-600 hover:text-navy-600 rounded-lg hover:bg-navy-50 transition-colors">Browse</a>
          <a href="#" class="px-4 py-2 text-sm font-medium text-gray-600 hover:text-navy-600 rounded-lg hover:bg-navy-50 transition-colors">Help</a>
          <div class="w-px h-5 bg-gray-200 mx-2"></div>
          <a href="#" class="px-4 py-2 text-sm font-medium text-navy-600 hover:bg-navy-50 rounded-lg transition-colors">Log In</a>
          <a href="#" class="px-5 py-2.5 text-sm font-semibold text-navy-600 bg-accent-400 hover:bg-accent-500 rounded-lg transition-colors btn-press shadow-sm">Sign Up</a>
        </nav>

        <!-- Mobile hamburger -->
        <button id="menu-toggle" class="md:hidden p-2 rounded-lg hover:bg-gray-100 transition-colors" aria-label="Open menu">
          <i data-lucide="menu" class="w-6 h-6 text-navy-600"></i>
        </button>
      </div>
    </div>
  </header>

  <!-- Mobile menu overlay -->
  <div id="mobile-overlay" class="mobile-menu-overlay"></div>
  <!-- Mobile menu drawer -->
  <div id="mobile-drawer" class="mobile-menu-drawer">
    <div class="p-5">
      <div class="flex items-center justify-between mb-8">
        <span class="text-lg font-bold text-navy-600">Med<span class="text-accent-400">Book</span></span>
        <button id="menu-close" class="p-2 rounded-lg hover:bg-gray-100 transition-colors" aria-label="Close menu">
          <i data-lucide="x" class="w-5 h-5 text-gray-500"></i>
        </button>
      </div>
      <nav class="flex flex-col gap-1">
        <a href="#specialties" class="mobile-nav-link px-4 py-3 text-base font-medium text-gray-700 hover:text-navy-600 hover:bg-navy-50 rounded-lg transition-colors">Browse</a>
        <a href="#" class="mobile-nav-link px-4 py-3 text-base font-medium text-gray-700 hover:text-navy-600 hover:bg-navy-50 rounded-lg transition-colors">Help</a>
        <a href="#" class="mobile-nav-link px-4 py-3 text-base font-medium text-gray-700 hover:text-navy-600 hover:bg-navy-50 rounded-lg transition-colors">Log In</a>
        <a href="#" class="mt-3 px-4 py-3 text-base font-semibold text-center text-navy-600 bg-accent-400 hover:bg-accent-500 rounded-lg transition-colors btn-press">Sign Up</a>
      </nav>
    </div>
  </div>

  <main>
    <!-- ============ HERO ============ -->
    <section class="relative overflow-hidden bg-gradient-to-b from-navy-50/60 via-white to-white">
      <!-- Decorative blobs -->
      <div class="absolute top-0 left-1/2 -translate-x-1/2 w-[800px] h-[600px] bg-accent-100/30 rounded-full blur-3xl -translate-y-1/2 pointer-events-none"></div>
      <div class="absolute bottom-0 right-0 w-[400px] h-[400px] bg-navy-100/20 rounded-full blur-3xl translate-y-1/2 pointer-events-none"></div>

      <div class="relative max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 pt-16 pb-10 md:pt-24 md:pb-16 text-center">
        <!-- Badge -->
        <div class="inline-flex items-center gap-2 px-4 py-1.5 bg-navy-600/5 border border-navy-600/10 rounded-full mb-6 fade-in-up">
          <span class="w-2 h-2 bg-mint-500 rounded-full animate-pulse"></span>
          <span class="text-xs font-semibold text-navy-600 tracking-wide uppercase">Same-day appointments available</span>
        </div>

        <h1 class="text-4xl sm:text-5xl md:text-6xl lg:text-7xl font-extrabold text-navy-600 tracking-tight leading-[1.1] mb-5 fade-in-up">
          Find and book<br class="hidden sm:block"> the care you need
        </h1>
        <p class="max-w-2xl mx-auto text-lg md:text-xl text-gray-500 leading-relaxed mb-10 fade-in-up">
          Search thousands of doctors, dentists, and specialists. Read verified patient reviews. Book appointments instantly — even same-day. It's that easy, and always free.
        </p>

        <!-- ============ SEARCH BAR ============ -->
        <div class="max-w-4xl mx-auto fade-in-up">
          <form id="search-form" class="bg-white rounded-2xl shadow-xl shadow-navy-600/8 border border-gray-100 p-2 sm:p-3" autocomplete="off">
            <div class="flex flex-col sm:flex-row gap-2 sm:gap-3">
              <!-- Specialty / Condition / Doctor -->
              <div class="relative flex-1 search-field rounded-xl border border-gray-200 transition-all">
                <div class="flex items-center px-3 py-2.5">
                  <i data-lucide="search" class="w-5 h-5 text-gray-400 shrink-0 mr-2"></i>
                  <input
                    id="search-input"
                    type="text"
                    placeholder="Condition, specialty, or doctor name"
                    class="w-full text-sm text-gray-800 placeholder-gray-400 bg-transparent outline-none"
                    aria-label="Search by condition, specialty, or doctor name"
                  >
                </div>
                <!-- Autocomplete dropdown -->
                <div id="autocomplete-dropdown" class="autocomplete-dropdown" role="listbox">
                  <!-- Items injected by JS -->
                </div>
              </div>

              <!-- Location -->
              <div class="relative sm:w-48 search-field rounded-xl border border-gray-200 transition-all">
                <div class="flex items-center px-3 py-2.5">
                  <i data-lucide="map-pin" class="w-5 h-5 text-gray-400 shrink-0 mr-2"></i>
                  <input
                    id="location-input"
                    type="text"
                    placeholder="City, state, or zip"
                    class="w-full text-sm text-gray-800 placeholder-gray-400 bg-transparent outline-none"
                    aria-label="Location"
                  >
                  <button type="button" id="geolocate-btn" class="shrink-0 ml-1 p-1 rounded-md hover:bg-navy-50 transition-colors" aria-label="Use my location" title="Use my location">
                    <i data-lucide="crosshair" class="w-4 h-4 text-navy-400"></i>
                  </button>
                </div>
              </div>

              <!-- Insurance -->
              <div class="relative sm:w-44 search-field rounded-xl border border-gray-200 transition-all">
                <div class="flex items-center px-3 py-2.5">
                  <i data-lucide="shield-check" class="w-5 h-5 text-gray-400 shrink-0 mr-2"></i>
                  <select
                    id="insurance-select"
                    class="w-full text-sm text-gray-800 bg-transparent outline-none appearance-none cursor-pointer"
                    aria-label="Insurance plan"
                  >
                    <option value="">Insurance plan</option>
                    <option value="aetna">Aetna</option>
                    <option value="bluecross">Blue Cross Blue Shield</option>
                    <option value="cigna">Cigna</option>
                    <option value="united">UnitedHealthcare</option>
                    <option value="kaiser">Kaiser Permanente</option>
                    <option value="humana">Humana</option>
                    <option value="anthem">Anthem</option>
                    <option value="other">Other</option>
                    <option value="none">No Insurance</option>
                  </select>
                  <i data-lucide="chevron-down" class="w-4 h-4 text-gray-400 shrink-0 ml-1 pointer-events-none"></i>
                </div>
              </div>

              <!-- Search button -->
              <button type="submit" class="bg-navy-600 hover:bg-navy-500 text-white font-semibold px-8 py-3 rounded-xl transition-colors btn-press shadow-lg shadow-navy-600/20 flex items-center justify-center gap-2">
                <i data-lucide="search" class="w-4 h-4"></i>
                <span>Search</span>
              </button>
            </div>
          </form>
        </div>
      </div>
    </section>

    <!-- ============ STATS BAR ============ -->
    <section class="bg-navy-600 py-8 md:py-10">
      <div class="max-w-5xl mx-auto px-4 sm:px-6 lg:px-8">
        <div class="grid grid-cols-2 md:grid-cols-4 gap-6 md:gap-8 text-center">
          <div class="stat-item">
            <div class="text-3xl md:text-4xl font-extrabold text-accent-400 mb-1">4.8M+</div>
            <div class="text-sm text-navy-200 font-medium">Verified patient reviews</div>
          </div>
          <div class="stat-item">
            <div class="text-3xl md:text-4xl font-extrabold text-accent-400 mb-1">12,000+</div>
            <div class="text-sm text-navy-200 font-medium">Healthcare providers</div>
          </div>
          <div class="stat-item">
            <div class="text-3xl md:text-4xl font-extrabold text-mint-400 mb-1">Same-day</div>
            <div class="text-sm text-navy-200 font-medium">Appointments available</div>
          </div>
          <div class="stat-item">
            <div class="text-3xl md:text-4xl font-extrabold text-mint-400 mb-1">100% free</div>
            <div class="text-sm text-navy-200 font-medium">For patients — always</div>
          </div>
        </div>
      </div>
    </section>

    <!-- ============ SPECIALTIES ============ -->
    <section id="specialties" class="py-16 md:py-24 bg-white">
      <div class="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div class="text-center mb-12 fade-in-up">
          <h2 class="text-3xl md:text-4xl font-extrabold text-navy-600 mb-3">Popular specialties</h2>
          <p class="text-gray-500 text-lg max-w-xl mx-auto">Find the right provider for your needs. Browse by specialty to see top-rated doctors near you.</p>
        </div>
        <div class="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-6 gap-4 md:gap-5 stagger-children">
          <!-- Primary Care -->
          <a href="#" class="specialty-card card-lift bg-white border border-gray-100 rounded-2xl p-5 text-center hover:border-navy-200 transition-all fade-in-up group" data-specialty="primary-care">
            <div class="specialty-icon w-14 h-14 mx-auto mb-3 bg-navy-50 rounded-xl flex items-center justify-center text-navy-600 transition-all">
              <i data-lucide="stethoscope" class="w-7 h-7"></i>
            </div>
            <h3 class="font-semibold text-navy-600 text-sm mb-1">Primary Care</h3>
            <p class="text-xs text-gray-400 leading-relaxed">Checkups & preventive care</p>
          </a>
          <!-- Dentist -->
          <a href="#" class="specialty-card card-lift bg-white border border-gray-100 rounded-2xl p-5 text-center hover:border-navy-200 transition-all fade-in-up group" data-specialty="dentist">
            <div class="specialty-icon w-14 h-14 mx-auto mb-3 bg-navy-50 rounded-xl flex items-center justify-center text-navy-600 transition-all">
              <i data-lucide="smile" class="w-7 h-7"></i>
            </div>
            <h3 class="font-semibold text-navy-600 text-sm mb-1">Dentist</h3>
            <p class="text-xs text-gray-400 leading-relaxed">Cleanings & oral health</p>
          </a>
          <!-- Dermatologist -->
          <a href="#" class="specialty-card card-lift bg-white border border-gray-100 rounded-2xl p-5 text-center hover:border-navy-200 transition-all fade-in-up group" data-specialty="dermatologist">
            <div class="specialty-icon w-14 h-14 mx-auto mb-3 bg-navy-50 rounded-xl flex items-center justify-center text-navy-600 transition-all">
              <i data-lucide="scan-face" class="w-7 h-7"></i>
            </div>
            <h3 class="font-semibold text-navy-600 text-sm mb-1">Dermatologist</h3>
            <p class="text-xs text-gray-400 leading-relaxed">Skin, acne & cosmetics</p>
          </a>
          <!-- Psychiatrist -->
          <a href="#" class="specialty-card card-lift bg-white border border-gray-100 rounded-2xl p-5 text-center hover:border-navy-200 transition-all fade-in-up group" data-specialty="psychiatrist">
            <div class="specialty-icon w-14 h-14 mx-auto mb-3 bg-navy-50 rounded-xl flex items-center justify-center text-navy-600 transition-all">
              <i data-lucide="brain" class="w-7 h-7"></i>
            </div>
            <h3 class="font-semibold text-navy-600 text-sm mb-1">Psychiatrist</h3>
            <p class="text-xs text-gray-400 leading-relaxed">Mental health & medication</p>
          </a>
          <!-- Eye Doctor -->
          <a href="#" class="specialty-card card-lift bg-white border border-gray-100 rounded-2xl p-5 text-center hover:border-navy-200 transition-all fade-in-up group" data-specialty="eye-doctor">
            <div class="specialty-icon w-14 h-14 mx-auto mb-3 bg-navy-50 rounded-xl flex items-center justify-center text-navy-600 transition-all">
              <i data-lucide="eye" class="w-7 h-7"></i>
            </div>
            <h3 class="font-semibold text-navy-600 text-sm mb-1">Eye Doctor</h3>
            <p class="text-xs text-gray-400 leading-relaxed">Vision & eye health</p>
          </a>
          <!-- Orthopedic Surgeon -->
          <a href="#" class="specialty-card card-lift bg-white border border-gray-100 rounded-2xl p-5 text-center hover:border-navy-200 transition-all fade-in-up group" data-specialty="orthopedic">
            <div class="specialty-icon w-14 h-14 mx-auto mb-3 bg-navy-50 rounded-xl flex items-center justify-center text-navy-600 transition-all">
              <i data-lucide="bone" class="w-7 h-7"></i>
            </div>
            <h3 class="font-semibold text-navy-600 text-sm mb-1">Orthopedic</h3>
            <p class="text-xs text-gray-400 leading-relaxed">Joint pain & sports injuries</p>
          </a>
        </div>
      </div>
    </section>

    <!-- ============ HOW IT WORKS ============ -->
    <section class="py-16 md:py-24 bg-gray-50/80">
      <div class="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div class="text-center mb-14 fade-in-up">
          <h2 class="text-3xl md:text-4xl font-extrabold text-navy-600 mb-3">How it works</h2>
          <p class="text-gray-500 text-lg max-w-xl mx-auto">Booking an appointment has never been easier. Three simple steps and you're done.</p>
        </div>
        <div class="grid md:grid-cols-3 gap-8 md:gap-6 lg:gap-12 relative stagger-children">
          <!-- Connector lines (desktop only) -->
          <div class="hidden md:block absolute top-16 left-[calc(16.67%+2rem)] right-[calc(16.67%+2rem)] h-0.5">
            <div class="w-full h-full bg-gradient-to-r from-navy-200 via-accent-300 to-mint-400 rounded-full" style="background: repeating-linear-gradient(90deg, #D5D0ED 0, #D5D0ED 8px, transparent 8px, transparent 16px);"></div>
          </div>

          <!-- Step 1 -->
          <div class="fade-in-up text-center relative">
            <div class="relative inline-flex items-center justify-center w-16 h-16 bg-white border-2 border-navy-200 rounded-2xl shadow-sm mb-5 z-10">
              <i data-lucide="search" class="w-7 h-7 text-navy-600"></i>
              <span class="absolute -top-2 -right-2 w-6 h-6 bg-accent-400 rounded-full flex items-center justify-center text-xs font-bold text-navy-700">1</span>
            </div>
            <h3 class="text-lg font-bold text-navy-600 mb-2">Search for a provider</h3>
            <p class="text-gray-500 text-sm leading-relaxed max-w-xs mx-auto">Enter your specialty, condition, or doctor name along with your location and insurance. Browse detailed provider profiles with photos, credentials, and office hours.</p>
          </div>

          <!-- Step 2 -->
          <div class="fade-in-up text-center relative">
            <div class="relative inline-flex items-center justify-center w-16 h-16 bg-white border-2 border-navy-200 rounded-2xl shadow-sm mb-5 z-10">
              <i data-lucide="calendar-check" class="w-7 h-7 text-navy-600"></i>
              <span class="absolute -top-2 -right-2 w-6 h-6 bg-accent-400 rounded-full flex items-center justify-center text-xs font-bold text-navy-700">2</span>
            </div>
            <h3 class="text-lg font-bold text-navy-600 mb-2">Choose a time that works</h3>
            <p class="text-gray-500 text-sm leading-relaxed max-w-xs mx-auto">View real-time availability and pick an appointment slot that fits your schedule — including same-day and next-day options.</p>
          </div>

          <!-- Step 3 -->
          <div class="fade-in-up text-center relative">
            <div class="relative inline-flex items-center justify-center w-16 h-16 bg-white border-2 border-mint-400 rounded-2xl shadow-sm mb-5 z-10">
              <i data-lucide="check-circle-2" class="w-7 h-7 text-mint-500"></i>
