  <script>
    // Initialize Lucide icons
    lucide.createIcons();

    // ---- Mobile Menu ----
    const menuToggle = document.getElementById('menu-toggle');
    const menuClose = document.getElementById('menu-close');
    const overlay = document.getElementById('mobile-overlay');
    const drawer = document.getElementById('mobile-drawer');

    function openMenu() {
      overlay.classList.add('active');
      drawer.classList.add('active');
      document.body.style.overflow = 'hidden';
    }
    function closeMenu() {
      overlay.classList.remove('active');
      drawer.classList.remove('active');
      document.body.style.overflow = '';
    }

    menuToggle.addEventListener('click', openMenu);
    menuClose.addEventListener('click', closeMenu);
    overlay.addEventListener('click', closeMenu);
    document.querySelectorAll('.mobile-nav-link').forEach(link => {
      link.addEventListener('click', closeMenu);
    });

    // ---- Search Autocomplete ----
    const searchInput = document.getElementById('search-input');
    const dropdown = document.getElementById('autocomplete-dropdown');
    let highlightedIndex = -1;

    const suggestions = [
      { icon: 'stethoscope', label: 'Primary Care', type: 'Specialty' },
      { icon: 'smile', label: 'Dentist', type: 'Specialty' },
      { icon: 'scan-face', label: 'Dermatologist', type: 'Specialty' },
      { icon: 'brain', label: 'Psychiatrist', type: 'Specialty' },
      { icon: 'eye', label: 'Eye Doctor', type: 'Specialty' },
      { icon: 'bone', label: 'Orthopedic Surgeon', type: 'Specialty' },
      { icon: 'heart-pulse', label: 'Cardiologist', type: 'Specialty' },
      { icon: 'baby', label: 'Pediatrician', type: 'Specialty' },
      { icon: 'activity', label: 'Back Pain', type: 'Condition' },
      { icon: 'thermometer', label: 'Cold & Flu', type: 'Condition' },
      { icon: 'zap', label: 'Migraine', type: 'Condition' },
      { icon: 'moon', label: 'Insomnia', type: 'Condition' },
      { icon: 'user', label: 'Dr. Sarah Chen', type: 'Doctor' },
      { icon: 'user', label: 'Dr. James Williams', type: 'Doctor' },
      { icon: 'user', label: 'Dr. Maria Garcia', type: 'Doctor' },
    ];

    function renderSuggestions(filtered) {
      if (filtered.length === 0) {
        dropdown.classList.remove('active');
        return;
      }
      dropdown.innerHTML = filtered.map((s, i) => `
        <div class="autocomplete-item ${i === highlightedIndex ? 'highlighted' : ''}" data-index="${i}" role="option">
          <i data-lucide="${s.icon}" style="width:16px;height:16px;color:#9CA3AF;flex-shrink:0"></i>
          <span class="flex-1">${s.label}</span>
          <span class="text-[10px] font-medium px-1.5 py-0.5 rounded bg-gray-100 text-gray-400">${s.type}</span>
        </div>
      `).join('');
      dropdown.classList.add('active');
      lucide.createIcons();

      // Click handlers on items
      dropdown.querySelectorAll('.autocomplete-item').forEach(item => {
        item.addEventListener('click', () => {
          searchInput.value = filtered[parseInt(item.dataset.index)].label;
          dropdown.classList.remove('active');
        });
      });
    }

    searchInput.addEventListener('input', () => {
      const val = searchInput.value.trim().toLowerCase();
      highlightedIndex = -1;
      if (!val) { dropdown.classList.remove('active'); return; }
      const filtered = suggestions.filter(s =>
        s.label.toLowerCase().includes(val) || s.type.toLowerCase().includes(val)
      );
      renderSuggestions(filtered);
    });

    searchInput.addEventListener('focus', () => {
      if (searchInput.value.trim()) {
        searchInput.dispatchEvent(new Event('input'));
      }
    });

    searchInput.addEventListener('keydown', (e) => {
      const items = dropdown.querySelectorAll('.autocomplete-item');
      if (!items.length) return;

      if (e.key === 'ArrowDown') {
        e.preventDefault();
        highlightedIndex = Math.min(highlightedIndex + 1, items.length - 1);
        updateHighlight(items);
      } else if (e.key === 'ArrowUp') {
        e.preventDefault();
        highlightedIndex = Math.max(highlightedIndex - 1, 0);
        updateHighlight(items);
      } else if (e.key === 'Enter' && highlightedIndex >= 0) {
        e.preventDefault();
        items[highlightedIndex].click();
      } else if (e.key === 'Escape') {
        dropdown.classList.remove('active');
      }
    });

    function updateHighlight(items) {
      items.forEach((item, i) => {
        item.classList.toggle('highlighted', i === highlightedIndex);
      });
    }

    document.addEventListener('click', (e) => {
      if (!e.target.closest('#search-input') && !e.target.closest('#autocomplete-dropdown')) {
        dropdown.classList.remove('active');
      }
    });

    // ---- Geolocation button ----
    const geolocateBtn = document.getElementById('geolocate-btn');
    const locationInput = document.getElementById('location-input');
    geolocateBtn.addEventListener('click', () => {
      if (!navigator.geolocation) return;
      locationInput.value = 'Detecting location...';
      navigator.geolocation.getCurrentPosition(
        (pos) => {
          locationInput.value = `${pos.coords.latitude.toFixed(2)}, ${pos.coords.longitude.toFixed(2)}`;
        },
        () => {
          locationInput.value = '';
        }
      );
    });

    // ---- Search Form Submit ----
    document.getElementById('search-form').addEventListener('submit', (e) => {
      e.preventDefault();
      const query = searchInput.value.trim();
